WITH base AS (SELECT *, TO_DATE(txn_time) AS txn_time_date, COALESCE(merchant, 'N/A') AS merchant_filled FROM transactions WHERE amount >= 3400), flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) + INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_burst FROM base), sessions_transactions AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT DATE_TRUNC('YEAR', txn_time_date) AS year_start, ROUND(SUM(burst_id) / NULLIF(COUNT(CASE WHEN txn_type = 'DEBIT' THEN 1 END), 0), 2) AS burst_id_per_debit, ROUND(AVG(burst_id), 2) AS avg_burst_id, SUM(burst_id) FILTER (WHERE merchant = '7-Eleven') AS 7_eleven_total_burst_id, SIZE(COLLECT_SET(txn_type)) AS num_txn_types, COUNT_IF(merchant = 'Lazada') AS lazada_events, AVG(is_new_burst) FILTER (WHERE txn_type = 'DEBIT') AS debit_avg_is_new_burst FROM sessions_transactions GROUP BY DATE_TRUNC('YEAR', txn_time_date) ORDER BY lazada_events NULLS LAST
